#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by vfx-maker. The prefab is rebuilt from this script: edit here, not in the Inspector.
    // Plan: Docs/VFX/__EFFECT__/Plan.md
    public static class __EFFECT__Build
    {
        const string Effect = "__EFFECT__";
        const string Root = "Assets/VFX/" + Effect;

        [MenuItem("VFX/" + Effect + "/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Textures", "Prefabs", "Scenes");

            // 1. Textures
            var glow = ImportTexture(Root + "/Textures/T_Glow_Soft.png", 256);

            // 2. Materials
            var mFlash = Material(Root + "/Materials/M_" + Effect + "_Flash_Add.mat", VfxBlend.Additive, glow);

            // 3. Layers
            var root = new GameObject("VFX_" + Effect);

            var flash = Particle(root.transform, "Flash", mFlash, lifetime: 0.15f, size: 2.5f, color: new Color(1f, 0.85f, 0.5f));
            SizeOverLifetime(flash, 0f, 0.5f, 1f, 1.2f);
            AlphaOverLifetime(flash, 0f, 1f, 1f, 0f);

            // 4. Save, validate, preview, demo scene
            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_" + Effect + ".prefab");
            Finish(prefab, Root, Effect, new[] { 0.03f, 0.1f, 0.25f, 0.5f, 1f });
        }

        public static void BuildBatch() => RunBatch(Build);
    }
}
#endif
